ALTER POLICY commission_read ON public.commissions USING (owner_id=auth.uid() OR ((public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'dir') OR public.has_role(auth.uid(),'it')) AND public.can_read_scope(owner_id,team_id,project_id)));
CREATE OR REPLACE FUNCTION public.apply_lead_change(_request uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.lead_change_requests; p jsonb; BEGIN IF NOT public.has_role(auth.uid(),'it') THEN RAISE EXCEPTION 'Maintenance access denied'; END IF; SELECT * INTO q FROM public.lead_change_requests WHERE id=_request AND requested_by=auth.uid() AND status='approved' FOR UPDATE; IF q.id IS NULL OR NOT public.has_role(q.approved_by,'sm') THEN RAISE EXCEPTION 'SM approval required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.sales_leads l JOIN public.user_roles r ON r.user_id=q.approved_by WHERE l.id=q.lead_id AND (r.user_id=l.owner_id OR r.project_id=l.project_id OR EXISTS(SELECT 1 FROM public.sales_projects p WHERE p.id=l.project_id AND p.created_by=r.user_id))) THEN RAISE EXCEPTION 'Approver scope changed'; END IF; p:=q.proposed; UPDATE public.sales_leads SET nickname=split_part(p->>'prospect_name',' ',1),prospect_name=p->>'prospect_name',phone=p->>'phone',address=p->>'address',source=p->>'source',status=p->>'status',verified_by=NULL,verified_at=NULL WHERE id=q.lead_id; UPDATE public.lead_change_requests SET status='applied',applied_at=now() WHERE id=q.id; END $$;